// ──────────────────────────────────────────────────────────────────────────────
// ILAS — CLERK 1: the clerk's signing key. WRITER SIDE ONLY.
//
// The key is generated by the clerk, held by the clerk, and never handed to a
// submitter through any interface in client.ts or clerkd.ts. There is no
// operation in the submit protocol that returns it, and no method on ClerkCore
// that exports it.
//
// WHAT THIS DOES NOT ACHIEVE, stated here rather than assumed:
//   The key file is written 0600, which excludes OTHER OS principals. It does
//   NOT exclude the observed system when the observed system runs as the SAME
//   principal — that user can simply read the file. Making the key unreadable
//   by the observed system requires running the clerk as its own OS user (or a
//   hardware-backed key, which is rung 2 and is fenced and undispatched). That
//   is a deployment act. This build stamps the principal it ran as so the gap
//   is visible in the record instead of being papered over.
// ──────────────────────────────────────────────────────────────────────────────

import {
  createPublicKey,
  generateKeyPairSync,
  createPrivateKey,
  sign as cryptoSign,
  KeyObject,
} from "crypto";
import { chmodSync, existsSync, readFileSync, writeFileSync } from "fs";
import { dirname } from "path";
import { requireClerkStoreDir } from "./store";

export interface ClerkKeys {
  privateKey: KeyObject;
  /** base64 SPKI DER. */
  publicKeyB64: string;
  /** true when this call generated a new key rather than loading one. */
  created: boolean;
}

function publicB64(privateKey: KeyObject): string {
  return createPublicKey(privateKey)
    .export({ type: "spki", format: "der" })
    .toString("base64");
}

/**
 * Load the clerk's key from `keyPath`, or generate and persist one if absent.
 * Also (re)writes the public key alongside it as a convenience copy.
 */
export function loadOrCreateKeys(
  keyPath: string,
  publicKeyPath: string
): ClerkKeys {
  if (existsSync(keyPath)) {
    const pem = readFileSync(keyPath, "utf8");
    const privateKey = createPrivateKey(pem);
    const publicKeyB64 = publicB64(privateKey);
    writeFileSync(publicKeyPath, publicKeyB64 + "\n", "utf8");
    return { privateKey, publicKeyB64, created: false };
  }

  // ── THE CLERK DOES NOT CREATE THE DIRECTORY ITS KEY LIVES IN (S96-D, S97) ──
  //
  //   This line was `mkdirSync(dirname(keyPath), { recursive: true })` until
  //   2026-08-31. The key file lives inside the clerk store directory, so this
  //   is the same act as `store.ts` — recipe §4.1, `2750
  //   mica-clerk:mica-readers` — reached from a second door. Cutting it there
  //   and leaving it here would have left the act skippable from this side,
  //   which is exactly how the intake cut survived S86 and had to be made
  //   twice.
  //
  //   THE CONSEQUENCE IS DELIBERATE AND IS NOT A DEFECT: on a box where the
  //   deployment act was never performed, the key-generation path below is now
  //   unreachable. The act comes first. A signing key generated into a
  //   directory conjured at the process umask is a key whose custody nobody
  //   ever decided — and custody of this key is already named as nobody's job
  //   (recipe §5.4.4 says it for the witness key; the clerk key is the same
  //   class, `[owed → board]`).
  //
  //   KEY GENERATION ITSELF IS UNTOUCHED BY THIS CUT. Everything below this
  //   line is byte-identical to the S96 tree; only the directory conjuring is
  //   gone.
  requireClerkStoreDir(
    dirname(keyPath),
    "clerk key directory",
    ", and no key was generated"
  );
  const { privateKey } = generateKeyPairSync("ed25519");
  const pem = privateKey.export({ type: "pkcs8", format: "pem" }) as string;

  writeFileSync(keyPath, pem, { encoding: "utf8", mode: 0o600 });
  try {
    // Windows ignores POSIX modes; the try/catch keeps that from being fatal,
    // and the principal stamped in every record is what actually carries the
    // honest statement of who can read this file.
    chmodSync(keyPath, 0o600);
  } catch {
    /* best effort — see the header note */
  }

  const publicKeyB64 = publicB64(privateKey);
  writeFileSync(publicKeyPath, publicKeyB64 + "\n", "utf8");
  return { privateKey, publicKeyB64, created: true };
}

/** Detached Ed25519 signature over the preimage, base64. */
export function signPreimage(preimage: string, privateKey: KeyObject): string {
  return cryptoSign(null, Buffer.from(preimage, "utf8"), privateKey).toString(
    "base64"
  );
}
